from modules.route_calculator import calculate_complete_route

# Circular route generated by our route optimizer
route = ["PAR", "LYO", "STR", "PAR"]

result = calculate_complete_route(route)

if result:

    print("\n========== FINAL TRIP SUMMARY ==========")

    print("Route:", " → ".join(route))

    print(
        "Total distance:",
        result["total_distance_km"],
        "KM"
    )

    print(
        "Total driving hours:",
        round(result["total_duration_minutes"] / 60, 2)
    )